// Ported from cloud-portal app/modules/metrics/utils/query-builders.ts at a7010d0e. Keep the
// output byte-for-byte identical: the jest tests pin it against strings generated by the
// portal's own functions.

export interface PrometheusLabelFilter {
  /** Label name in Prometheus. */
  label: string;
  /** One value (exact match), several (regex OR), or nothing (no matcher). */
  value: string | readonly string[] | null | undefined;
}

export interface PrometheusSelectorOptions {
  /** Always included, always quoted: `label="value"`. */
  baseLabels: Record<string, string>;
  filters?: PrometheusLabelFilter[];
  /**
   * Values starting with an operator (`!`, `=`, `~`) are used as-is
   * (`label!=""`); anything else is quoted (`label="value"`).
   */
  customLabels?: Record<string, string>;
}

/** `{a="1",b!="",c=~"x|y"}`: base labels, then custom labels, then filters. */
export function buildPrometheusLabelSelector({
  baseLabels,
  filters = [],
  customLabels = {},
}: PrometheusSelectorOptions): string {
  const all: string[] = [];
  for (const [key, value] of Object.entries(baseLabels)) all.push(`${key}="${value}"`);
  for (const [key, value] of Object.entries(customLabels)) {
    all.push(/^[!~=]/.test(value) ? `${key}${value}` : `${key}="${value}"`);
  }
  for (const { label, value } of filters) {
    if (!value) continue;
    if (Array.isArray(value)) {
      if (value.length > 0) all.push(`${label}=~"${value.join('|')}"`);
    } else if (typeof value === 'string' && value.trim()) {
      all.push(`${label}="${value}"`);
    }
  }
  return `{${all.join(',')}}`;
}

export const REGION_LABEL = 'label_topology_kubernetes_io_region';

export function createRegionFilter(
  value: string | readonly string[] | null | undefined,
  label: string = REGION_LABEL
): PrometheusLabelFilter {
  return { label, value };
}

type Aggregation = 'sum' | 'avg' | 'min' | 'max';

interface AggregateOptions extends PrometheusSelectorOptions {
  metric: string;
  timeWindow: string;
  groupBy?: string[];
  aggregation?: Aggregation;
}

/** `sum(rate(metric{…}[window])) by (a,b)`. */
export function buildRateQuery({ metric, timeWindow, groupBy = [], aggregation = 'sum', ...selector }: AggregateOptions): string {
  const by = groupBy.length > 0 ? ` by (${groupBy.join(',')})` : '';
  return `${aggregation}(rate(${metric}${buildPrometheusLabelSelector(selector)}[${timeWindow}]))${by}`;
}

/** `histogram_quantile(q, sum(rate(metric{…}[window])) by (le))`. */
export function buildHistogramQuantileQuery({
  quantile,
  metric,
  timeWindow,
  groupBy = [],
  aggregation = 'sum',
  ...selector
}: AggregateOptions & { quantile: number }): string {
  const by = groupBy.length > 0 ? ` by (${groupBy.join(',')})` : '';
  return `histogram_quantile(${quantile}, ${aggregation}(rate(${metric}${buildPrometheusLabelSelector(selector)}[${timeWindow}]))${by})`;
}
